#include "ed_internal.h"
#include <stdio.h>

int main(int argc,char**argv){ed_model*m=NULL;ed_status s;uint32_t i;uint64_t parameters=0,trainable=0;if(argc<2||argc>3){fprintf(stderr,"usage: edinspect MODEL.edm [--tensors]\n");return 2;}s=ed_model_load(argv[1],&m);if(s!=ED_OK){fprintf(stderr,"load: %s\n",ed_status_string(s));return 1;}for(i=0;i<m->tensor_count;++i)if(m->tensors[i].dtype==ED_PRECISION_FP32){uint64_t n=m->tensors[i].data_bytes/4u;parameters+=n;if(m->tensors[i].flags&1u)trainable+=n;}printf("model=%s classes=%u tensors=%u precision=%u parameters=%llu trainable=%llu frozen=%llu\n",argv[1],m->class_count,m->tensor_count,m->precision,(unsigned long long)parameters,(unsigned long long)trainable,(unsigned long long)(parameters-trainable));for(i=0;i<m->class_count;++i)printf("class[%u]=%s\n",i,m->class_names[i]);if(argc==3){for(i=0;i<m->tensor_count;++i){const ed_tensor*t=&m->tensors[i];printf("tensor[%u]=%s rank=%u dims=%u,%u,%u,%u bytes=%llu flags=%u\n",i,t->name,t->rank,t->dims[0],t->dims[1],t->dims[2],t->dims[3],(unsigned long long)t->data_bytes,t->flags);}}ed_model_free(m);return 0;}
